WITH metrics AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, LEAD(discount_pct, 1) OVER (PARTITION BY promo_code ORDER BY ends_on, id) AS next_discount_pct, FIRST_VALUE(channel, TRUE) OVER w_hist AS first_known_channel FROM promotions WINDOW w_hist AS (ORDER BY ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT promo_code, channel, ROUND(AVG(next_discount_pct), 2) AS avg_next_discount_pct, APPROX_PERCENTILE(next_discount_pct, ARRAY(0.25, 0.5, 0.75)) AS next_discount_pct_quartiles, ROUND(SUM(discount_pct) / NULLIF(COUNT(CASE WHEN channel = 'mobile' THEN 1 END), 0), 2) AS discount_pct_per_mobile, RANK() OVER (PARTITION BY promo_code ORDER BY ROUND(AVG(next_discount_pct), 2) DESC) AS avg_next_discount_pct_rank FROM metrics GROUP BY 1, 2 ORDER BY promo_code DESC NULLS LAST
